// Parse Slack slash command payload
// Slack sends: token=...&text=tema+del+blog&command=%2Fblog&...
const body = $input.first().json.body || $input.first().json;

// Ignora eventos que no son el slash command (mensajes del bot, retries de Slack, etc)
if (body.bot_id || body.subtype === 'bot_message' || body.command !== '/blog') {
  return [];
}

// Slash command sends form-encoded body
const text = body.text || '';
const userId = body.user_id || body.user_name || 'unknown';
const channelId = body.channel_id || 'C0BN01LMC3F';
const responseUrl = body.response_url || '';

// Format: /blog tema del post | Categoria
// Category is optional, separated by |
const parts = text.split('|').map(s => s.trim());
const topic = parts[0] || text;
const category = parts[1] || 'UX Design';

if (!topic) {
  return [{ json: { error: 'Falta el tema. Uso: /blog tema del post | Categoria' } }];
}

return [{ json: { topic, category, userId, channelId, responseUrl } }];
